using System;using System.Text;using UnityEngine;using TMPro;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckFieldGoal {
public enum FieldGoalPhase{Countdown,Approach,Windup,BootSwing,Flight,Aftermath,Replay,AttemptResult}
public sealed class FieldGoalMatch:SportsEventSession {
 static readonly float[] Distances={30,38,46,54,62};
 public SportsEventTruck truck;public FieldGoalProjectile football,truckFlight;public FieldGoalBoot boot;public Collider ground;public Transform posts,tee,bootMechanism;public SportsEventCamera cameraRig;public SportsMotionReplay replay;public SportsChaosWeather atmosphere;public AudioSource flightWind;public TMP_Text practiceDistanceText;public GameObject practiceRetry;public ParticleSystem kickBurst;public FieldGoalRules rules=new FieldGoalRules();public int seed=18361,practiceDistance=2;public FieldGoalPhase Phase{get;private set;}public float Clock{get;private set;}public float PhaseAge{get;private set;}public float FlightAge{get;private set;}public float Timing{get;private set;}public string Outcome{get;private set;}="";public Vector3 CurrentWind{get;private set;}public bool IsTruck=>(option&1)!=0;public bool Practice=>option>=2;public float GoalZ=>Distances[Practice?Mathf.Clamp(practiceDistance,0,4):rules.Round>5?(rules.Round-6)%5:Mathf.Clamp(rules.Round-1,0,4)];public float GoalHalfWidth=>2.82f;public float Crossbar=>3.05f;public FieldGoalProjectile Projectile=>IsTruck?truckFlight:football;public readonly SportsLimitedAftertouch correction=new SportsLimitedAftertouch();
 readonly StringBuilder text=new StringBuilder(700);Vector2 ai;bool botAction;float aiThink,aimX,entryAngle,entrySpeed,tapTime;bool timingCommitted;
 public override string Title=>"TRUCK FIELD GOAL";public override int MinimumPlayers=>1;public override int MaximumPlayers=>Practice?1:4;public override int OptionCount=>4;public override int WeatherCount=>1;public override bool UsesAction=>IsTruck;public override bool ReplayControls=>Phase==FieldGoalPhase.Replay;public override string OptionLabel=>(IsTruck?"TRUCK IS THE FOOTBALL":"TRUCK IS THE FOOT")+(Practice?" · SOLO PRACTICE":" · FIVE ATTEMPTS");public override string SourcePolicy=>"Sequential attempts: shared keyboard/controller hot seat or separately assigned sources.\nOnly the current shooter drives. The same device may be reused between turns.";
 public override void NormalizeSetup(){base.NormalizeSetup();setup.mode=BowlingMode.HotSeat;setup.sharedHotSeat=true;practiceDistance=Mathf.Clamp(practiceDistance,0,4);}
 public override bool ValidateSources(out string reason){if(!setup.Validate(out reason))return false;if(UsesAction)for(int i=0;i<setup.count;i++){var p=setup.players[i];var key=actionKeys[i];if(p.source==BowlingSource.Keyboard&&(key==UnityEngine.InputSystem.Key.None||key==UnityEngine.InputSystem.Key.Escape||key==p.forward||key==p.left||key==p.back||key==p.right)){reason="Assign a separate boot-timing action for slot "+(i+1);return false;}}reason="";return true;}
 public override void RefreshExtraUI(){if(practiceDistanceText==null)return;practiceDistanceText.transform.parent.gameObject.SetActive(Practice);practiceDistanceText.text="PRACTICE DISTANCE · "+Mathf.RoundToInt(GoalZ/.9144f)+" YARDS";}
 public override string Header=>Title+" · "+(Practice?"PRACTICE":rules.Round<=5?"ATTEMPT "+rules.Round+" / 5":"EXTRA "+(rules.Round-5))+" · "+setup.players[rules.Current].name;
 public override string Status{get{string state=Phase==FieldGoalPhase.Countdown?"READY · "+Mathf.CeilToInt(3-PhaseAge):Phase==FieldGoalPhase.Approach?(IsTruck?"DRIVE INTO THE BOOT STRIKE AREA":"DRIVE INTO THE FOOTBALL · CONTACT IS THE KICK"):Phase==FieldGoalPhase.Windup?"BOOT TIMING  "+Meter(Mathf.Clamp01(PhaseAge/1.4f))+"  · ACTION AT THE CENTER MARK":Phase==FieldGoalPhase.BootSwing?"KICK COMMITTED · "+Mathf.RoundToInt(Timing*100)+"% TIMING":Phase==FieldGoalPhase.Flight?(IsTruck?"LIMITED AFTERTOUCH · "+Mathf.RoundToInt(Mathf.Max(0,1-correction.Spent/1.6f)*100)+"%":"FOOTBALL IN FLIGHT · NO AIR CONTROL"):Phase==FieldGoalPhase.Replay?"ACTUAL REPLAY · "+replay.Speed.ToString("0.##")+"× · CAMERA "+(replay.Angle+1):Outcome;return state+"\n"+Mathf.RoundToInt(GoalZ/.9144f)+" YARDS · WIND "+(CurrentWind.magnitude*2.236936f).ToString("F1")+" MPH · "+(CurrentWind.x>=0?"RIGHT":"LEFT");}}
 static string Meter(float value){int n=Mathf.Clamp(Mathf.RoundToInt(value*14),0,14);return new string('·',n)+"|"+new string('·',14-n);}
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(i==rules.Current?"> ":"").Append(setup.players[i].name).Append(" · ").Append(rules.goals[i]).Append(" GOOD / ").Append(rules.attempts[i]).Append(" KICKS\n");return text.ToString();}}
 public override string Results=>OptionLabel+"\n"+(setup.count==1?"TOTAL "+rules.goals[0]+" · BEST "+SportsPrefs.GetInt(BestKey,0):setup.players[rules.Winner].name+" WINS")+"\n\n"+Standings;string BestKey=>"TruckFieldGoal.Best."+(IsTruck?"Football":"Foot");
 public override string Help=>"TWO VARIANTS\nTRUCK IS THE FOOT: line up behind the real football and drive into it. Actual bumper contact determines direction, lift, power and spin. No kick button and no airborne ball control. The once-only contact response applies only the velocity difference needed for that contact-derived kick; repeated contacts cannot stack it.\n\nTRUCK IS THE FOOTBALL: drive into the marked boot area. Physical brakes hold the short windup; time one ACTION near the center mark. The visible boot must actually overlap your chassis before it launches you. Early/late taps weaken the kick; missed timing or missing the boot resolves safely. In flight, small bounded lateral/range nudges use a shared correction budget. Release fore/aft once after launch to arm range correction. No hovering, extra launch or post-landing driving.\n\nFIVE ATTEMPTS each at progressively greater distances. One point for a forward center crossing BETWEEN uprights and ABOVE the crossbar before first airborne ground contact. Side/back/below/wide entries are not goals. A real post/crossbar ricochet followed by a legal forward crossing counts. Swept crossing prevents fast tunneling; physics contact chronology takes precedence over callback order. Once GOOD, later collisions cannot revoke it. Tied leaders receive equal-opportunity extra rounds cycling the same five distances; first shooter rotates. Same goal geometry/distances and equivalent wind relative to launch apply to both variants and all participants.\n\nSOLO PRACTICE selects a fixed distance and keeps retrying. Separate variant personal best/statistics. Sequential hot seat may reuse a keyboard or controller; inactive players cannot affect the attempt. AI drives and times the same real contacts without homing or direct score awards. Actual-motion replay has angle, slow/normal/fast, rewind and skip. Pause/reconnect preserves the attempt; release inputs before fresh confirmation. Offline only.";
 protected override void Awake(){base.Awake();practiceDistance=Mathf.Clamp(SportsPrefs.GetInt("TruckFieldGoal.PracticeDistance",2),0,4);}
 protected override void BeginGame(){rules.Reset(setup.count,Practice);PrepareAttempt();}
 void PrepareAttempt(){replay.End();truck.visuals.gameObject.SetActive(true);football.gameObject.SetActive(true);boot.gameObject.SetActive(IsTruck);bootMechanism.gameObject.SetActive(IsTruck);tee.gameObject.SetActive(!IsTruck);Clock=PhaseAge=FlightAge=Timing=0;timingCommitted=false;Outcome="";Phase=FieldGoalPhase.Countdown;posts.position=new Vector3(0,0,GoalZ);truck.slot=rules.Current;truck.Prepare(new Vector3(0,.7f,IsTruck?-13:-27),Quaternion.identity);football.body.isKinematic=true;football.body.detectCollisions=!IsTruck;football.body.position=new Vector3(0,.75f,0);football.body.rotation=Quaternion.Euler(0,0,12);football.transform.SetPositionAndRotation(football.body.position,football.body.rotation);Physics.IgnoreCollision(football.shape,truck.shape,false);football.ResetShot();football.gameObject.SetActive(!IsTruck);truckFlight.ResetShot();boot.ResetBoot();correction.Reset(1.6f,Vector2.zero);kickBurst.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);atmosphere.Configure(seed+rules.Round*997,1,rules.Round>3?1:0);atmosphere.Tick(0);CurrentWind=atmosphere.Flow*Mathf.Lerp(.4f,1.7f,Mathf.Clamp01((rules.Round-1)/4f));replay.Colorize(new[]{setup.players[rules.Current].color,Color.white,Color.white});replay.ResetRecord();var random=new System.Random(seed+rules.Round*1009+rules.Current*7919);float skill=(int)setup.players[rules.Current].difficulty;aimX=(float)(random.NextDouble()*2-1)*Mathf.Lerp(.75f,.12f,skill*.5f);entryAngle=(float)(random.NextDouble()*2-1)*Mathf.Lerp(14,8,skill*.5f)-Mathf.Atan2(CurrentWind.x*.4f,GoalZ)*Mathf.Rad2Deg*Mathf.Lerp(.2f,.9f,skill*.5f);entrySpeed=IsTruck?7:Mathf.Sqrt(1.8f*GoalZ*GoalZ/Mathf.Max(1,.424f*GoalZ-5.35f));entrySpeed+=(float)(random.NextDouble()*2-1)*Mathf.Lerp(3.4f,.65f,skill*.5f);tapTime=.7f+(float)(random.NextDouble()*2-1)*Mathf.Lerp(.48f,.23f,skill*.5f);aiThink=0;ai=Vector2.zero;botAction=false;cameraRig.rig.PreviousStateIsValid=false;Physics.SyncTransforms();Gate();}
 protected override void Simulate(float dt){if(Projectile.Launched&&!rules.AttemptLocked)Projectile.Observe();Clock+=dt;PhaseAge+=dt;if(IsTruck&&boot.Stroking&&Phase!=FieldGoalPhase.Replay)boot.Tick(dt);if(Phase==FieldGoalPhase.Replay){if(replay.Step(dt)||PhaseAge>18){replay.End();truck.visuals.gameObject.SetActive(true);football.gameObject.SetActive(!IsTruck);boot.gameObject.SetActive(IsTruck);Phase=FieldGoalPhase.AttemptResult;PhaseAge=0;}return;}if(Phase==FieldGoalPhase.AttemptResult){if(PhaseAge>=1.2f){rules.Advance();if(rules.Complete){if(setup.count==1){SportsPrefs.SetInt(BestKey,Mathf.Max(SportsPrefs.GetInt(BestKey,0),rules.goals[0]));SportsPrefs.Save();}EndMatch();}else PrepareAttempt();}return;}if(Phase==FieldGoalPhase.Countdown){Brake(Vector2.zero);if(PhaseAge>=3){Phase=FieldGoalPhase.Approach;PhaseAge=0;}return;}
  Vector2 drive=commands[rules.Current];bool action=actions[rules.Current];if(setup.players[rules.Current].source==BowlingSource.AI){Bot(dt);drive=ai;action=botAction;}if(Phase==FieldGoalPhase.Approach){truck.TickDrive(drive);if(IsTruck&&truck.body.position.z>=-2.6f&&truck.body.position.z<=2.2f&&Mathf.Abs(truck.body.position.x)<3){Phase=FieldGoalPhase.Windup;PhaseAge=0;}if(PhaseAge>35||truck.body.position.y< -4||Mathf.Abs(truck.body.position.x)>25||truck.body.position.z>(IsTruck?5:15))Resolve(false,IsTruck?"MISSED THE BOOT":"MISSED THE BALL",truck.body.position);}
  else if(Phase==FieldGoalPhase.Windup){Brake(drive);if(action&&!timingCommitted){timingCommitted=true;Timing=Mathf.Clamp01(1-Mathf.Abs(PhaseAge-.7f)/.7f);Phase=FieldGoalPhase.BootSwing;PhaseAge=0;boot.Begin();feedback.Play(0,0,true);}else if(PhaseAge>1.5f)Resolve(false,"NO TIMED KICK",truck.body.position);}
  else if(Phase==FieldGoalPhase.BootSwing){Brake(Vector2.zero);if(PhaseAge>1.2f&&!truckFlight.Launched)Resolve(false,"OUTSIDE BOOT REACH",truck.body.position);}
  else if(Phase==FieldGoalPhase.Flight){FlightAge+=dt;if(IsTruck)correction.Tick(truck.body,drive,dt);atmosphere.Tick(FlightAge);CurrentWind=atmosphere.Flow*Mathf.Lerp(.4f,1.7f,Mathf.Clamp01((rules.Round-1)/4f));Projectile.body.AddForce(CurrentWind*.08f,ForceMode.Acceleration);var p=Projectile.Reference;if(FlightAge>12||p.y< -5||Mathf.Abs(p.x)>65||p.z>GoalZ+35||p.z< -25||FlightAge>.5f&&!Projectile.ClearedGround&&Projectile.shape.bounds.min.y<.13f)Resolve(false,string.IsNullOrEmpty(Projectile.LastMissLabel)?"SHORT / OUT OF PLAY":Projectile.LastMissLabel,p);}
  else if(Phase==FieldGoalPhase.Aftermath&&PhaseAge>2.2f)BeginReplay();replay.Record(Clock,IsTruck?5:3);
 }
 void Brake(Vector2 drive){truck.TickDrive(new Vector2(drive.x,0));foreach(var wheel in truck.wheels){wheel.MotorTorque=0;wheel.BrakeTorque=truck.brakeTorque;}}
 void Bot(float dt){botAction=false;aiThink-=dt;if(aiThink>0)return;float skill=(int)setup.players[rules.Current].difficulty;aiThink=Mathf.Lerp(.22f,.065f,skill*.5f);var p=truck.body.position;var forward=Vector3.ProjectOnPlane(truck.body.rotation*Vector3.forward,Vector3.up);if(Phase==FieldGoalPhase.Approach){bool lineUp=!IsTruck&&p.z<-17;float x=lineUp?aimX-Mathf.Tan(entryAngle*Mathf.Deg2Rad)*10:aimX;var delta=new Vector3(x-p.x,0,Mathf.Max(2,(lineUp?-16:0)-p.z));float angle=Vector3.SignedAngle(forward,delta,Vector3.up);ai=new Vector2(Mathf.Clamp(angle/24,-1,1),Mathf.Clamp((entrySpeed-truck.body.linearVelocity.z)*.5f,-.8f,1));}else if(Phase==FieldGoalPhase.Windup){ai=Vector2.zero;botAction=PhaseAge>=tapTime;}else if(Phase==FieldGoalPhase.Flight&&IsTruck){var b=truck.body;float time=Mathf.Max(0,(b.linearVelocity.y+Mathf.Sqrt(b.linearVelocity.y*b.linearVelocity.y+2*9.81f*Mathf.Max(0,b.position.y)))/9.81f);float prediction=b.position.x+b.linearVelocity.x*time;ai=new Vector2(Mathf.Clamp((-prediction+aimX)*Mathf.Lerp(.06f,.2f,skill*.5f),-1,1),FlightAge<.35f?0:Mathf.Clamp((GoalZ-b.position.z-b.linearVelocity.z*time)*.04f,-1,1));}else ai=Vector2.zero;}
 public void FootContact(Collision collision){if(IsTruck||Phase!=FieldGoalPhase.Approach||football.Launched)return;var incoming=Vector3.ProjectOnPlane(-collision.relativeVelocity,Vector3.up);if(Vector3.Dot(incoming,truck.body.rotation*Vector3.forward)<0)incoming=-incoming;float speed=incoming.magnitude;if(speed<1.5f)return;var point=collision.GetContact(0).point;float offset=point.x-football.Reference.x;var desired=incoming.normalized*Mathf.Clamp(speed*1.65f,3,32)+Vector3.right*(offset*speed*.6f)+Vector3.up*Mathf.Clamp(3+speed*.7f,5,17);football.body.isKinematic=false;football.body.AddForce(desired-football.body.linearVelocity,ForceMode.VelocityChange);football.body.angularVelocity=Vector3.ClampMagnitude(Vector3.Cross(point-football.Reference,incoming)*2+Vector3.Cross(Vector3.up,incoming.normalized)*(speed*.3f),20);truck.Power(false);Physics.IgnoreCollision(football.shape,truck.shape,true);football.Arm();Launched(point);}
 public void BootContact(Vector3 point){if(!IsTruck||Phase!=FieldGoalPhase.BootSwing||truckFlight.Launched||!timingCommitted)return;var velocity=boot.body.GetPointVelocity(point);var along=Vector3.ProjectOnPlane(velocity,Vector3.up);if(along.magnitude<1)return;var facing=Vector3.ProjectOnPlane(truck.body.rotation*Vector3.forward,Vector3.up).normalized;var direction=(along.normalized*.7f+facing*.3f).normalized;float quality=.45f+.55f*Timing;var desired=direction*(Mathf.Clamp(18+along.magnitude*.45f,18,32)*quality)+Vector3.up*(Mathf.Clamp(14+Mathf.Abs(velocity.y)*.15f,14,17)*quality);truck.Power(false);truck.body.AddForce(desired-truck.body.linearVelocity,ForceMode.VelocityChange);var spin=Vector3.ClampMagnitude(Vector3.Cross(point-truck.body.worldCenterOfMass,desired)*.055f,3);truck.body.AddTorque(spin-truck.body.angularVelocity,ForceMode.VelocityChange);correction.Reset(1.6f,commands[rules.Current]);truckFlight.Arm();Launched(point);}
 void Launched(Vector3 point){Phase=FieldGoalPhase.Flight;PhaseAge=FlightAge=0;kickBurst.transform.position=point;kickBurst.Play();feedback.Play(1,14,true);Pulse(rules.Current,.4f,.18f);Debug.Log("FIELD_GOAL_ACTUAL_KICK variant="+(IsTruck?"Truck":"Foot")+" round="+rules.Round+" shooter="+rules.Current+" point="+point+" queuedPhysicsResponse=true timing="+Timing);}
 public void Resolve(bool good,string reason,Vector3 point){if(!Live||!rules.Lock(good))return;Outcome=reason;Phase=FieldGoalPhase.Aftermath;PhaseAge=0;truck.Power(false);feedback.Play(good?5:3,0,true);Pulse(rules.Current,good?.6f:.2f,.2f);{string key="TruckFieldGoal.Statistics."+(IsTruck?"Football":"Foot");SportsPrefs.SetInt(key+".Attempts",SportsPrefs.GetInt(key+".Attempts",0)+1);if(good)SportsPrefs.SetInt(key+".Goals",SportsPrefs.GetInt(key+".Goals",0)+1);SportsPrefs.Save();}Debug.Log("FIELD_GOAL_RESULT variant="+(IsTruck?"Truck":"Foot")+" round="+rules.Round+" shooter="+rules.Current+" good="+good+" reason="+reason+" point="+point);}
 public void PostHit(float speed){feedback.Play(1,speed);Pulse(rules.Current,.18f,.08f);}
 void BeginReplay(){replay.Record(Clock+.051f,IsTruck?5:3);truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;football.body.isKinematic=true;football.body.detectCollisions=false;truck.visuals.gameObject.SetActive(false);football.gameObject.SetActive(false);boot.gameObject.SetActive(false);Phase=FieldGoalPhase.Replay;PhaseAge=0;replay.Begin(Mathf.Max(0,Clock-7));Gate();}
 public override void ExtraAction(string key){if(key=="distance"&&!Running){practiceDistance=(practiceDistance+1)%5;SportsPrefs.SetInt("TruckFieldGoal.PracticeDistance",practiceDistance);Save();return;}if(key=="retry"&&Practice&&Running&&!Paused){if(rules.AttemptLocked)rules.Advance();PrepareAttempt();return;}if(Phase!=FieldGoalPhase.Replay)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed==1?.5f:replay.Speed==.5f?2:1;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.Cursor-3));else if(key=="replayskip")PhaseAge=19;ConsumeActions();}
 protected override void Present(float dt){if(cameraRig==null||truck==null)return;if(practiceRetry!=null&&practiceRetry.activeSelf!=Practice)practiceRetry.SetActive(Practice);bool recorded=Phase==FieldGoalPhase.Replay;var focus=recorded?replay.Position(IsTruck||!football.Launched?0:1):Phase==FieldGoalPhase.Flight||Phase==FieldGoalPhase.Aftermath?(IsTruck||football.Launched?Projectile.Reference:truck.body.worldCenterOfMass):truck.body.worldCenterOfMass+Vector3.forward*6;Vector3 offset=recorded?(replay.Angle==0?new Vector3(10,6,-12):replay.Angle==1?new Vector3(-12,5,7):new Vector3(0,20,-2)):Phase==FieldGoalPhase.Flight?new Vector3(0,4,-10):new Vector3(0,3.5f,-9);cameraRig.Pose(focus,offset,60);if(flightWind!=null){flightWind.volume=Live&&Phase==FieldGoalPhase.Flight&&Application.isFocused?settings.sfx*.04f:0;if(flightWind.volume>0&&!flightWind.isPlaying)flightWind.Play();else if(flightWind.volume<=0)flightWind.Stop();}}
 protected override void SetPaused(bool paused){if(atmosphere!=null)atmosphere.Pause(paused);}protected override void StopSounds(){if(truck!=null)truck.StopSound();if(flightWind!=null)flightWind.Stop();}protected override void StopGame(){if(replay!=null)replay.End();if(truck!=null){truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;}if(football!=null){football.body.isKinematic=true;football.body.detectCollisions=false;}}
}
